python3 - <<'EOF'
import json, glob
for coin in ("btc","eth","sol","xrp","doge"):
    path = f"logs/{coin}/decisions.jsonl"
    n=0; stale3=0; src_counts={}
    try:
        with open(path) as fh:
            for line in fh:
                if '"health"' not in line: continue
                try: d=json.loads(line)
                except Exception: continue
                if d.get("kind")!="health": continue
                st=d.get("stale") or {}
                b=st.get("binance_s")
                if b is None: continue
                n+=1
                if b>3.0: stale3+=1
    except OSError:
        continue
    print(f"{coin}: {n} health lines, binance stale>3s on {stale3} ({stale3/max(n,1):.1%})")
EOF
